using System.Net;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>
/// A minimal <see cref="HttpMessageHandler"/> stand-in for the provider's REST API.
/// Records the last outgoing request body and replies with a pre-canned response,
/// so tests can assert on both what we send and how we interpret what comes back.
/// </summary>
internal sealed class StubHttpMessageHandler(HttpStatusCode statusCode, string? responseBody) : HttpMessageHandler
{
    public HttpRequestMessage? LastRequest { get; private set; }

    public string? LastRequestBody { get; private set; }

    protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
    {
        LastRequest = request;
        LastRequestBody = request.Content is null ? null : await request.Content.ReadAsStringAsync(cancellationToken);

        var response = new HttpResponseMessage(statusCode);
        if (responseBody is not null)
        {
            response.Content = new StringContent(responseBody, System.Text.Encoding.UTF8, "application/json");
        }

        return response;
    }
}

