using System.Net;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    private static (HttpPaymentGateway Gateway, StubHttpMessageHandler Handler) CreateGateway(HttpStatusCode statusCode, string? responseBody)
    {
        var handler = new StubHttpMessageHandler(statusCode, responseBody);
        var client = new HttpClient(handler) { BaseAddress = new Uri("https://provider.example") };
        return (new HttpPaymentGateway(client), handler);
    }

    [Fact]
    public async Task Sends_the_reference_amount_and_currency_the_provider_expects()
    {
        var (gateway, handler) = CreateGateway(HttpStatusCode.OK, """{"status":"approved"}""");

        await gateway.AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);

        Assert.Equal(HttpMethod.Post, handler.LastRequest!.Method);
        Assert.Equal("/v1/authorizations", handler.LastRequest.RequestUri!.AbsolutePath);

        using var body = JsonDocument.Parse(handler.LastRequestBody!);
        Assert.Equal("ORD-7", body.RootElement.GetProperty("reference").GetString());
        Assert.Equal(12.5m, body.RootElement.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", body.RootElement.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_response_is_read_back_as_Approved()
    {
        var (gateway, _) = CreateGateway(HttpStatusCode.OK, """{"status":"approved"}""");

        var outcome = await gateway.AuthorizeAsync("ORD-7", new Money(10m, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_200_response_with_status_declined_is_read_back_as_Declined()
    {
        var (gateway, _) = CreateGateway(HttpStatusCode.OK, """{"status":"declined"}""");

        var outcome = await gateway.AuthorizeAsync("ORD-7", new Money(10m, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_response_is_treated_as_Declined_even_without_a_body()
    {
        var (gateway, _) = CreateGateway(HttpStatusCode.PaymentRequired, responseBody: null);

        var outcome = await gateway.AuthorizeAsync("ORD-7", new Money(10m, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_response_with_a_body_is_still_treated_as_Declined()
